#include <stdio.h>

/* teste do desafio maior-nota — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: nao ha captura de stdout aqui. O teste declara o prototipo
   da caixa do aluno, chama-a e confere o VALOR devolvido com checa_int.
   Os tres cenarios poem o maximo em lugares diferentes da caixa: na
   primeira gaveta, na ultima e no meio — devolver sempre a mesma gaveta
   reprova em ao menos um deles. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int maiorNota(int primeira, int ultima);

SM_TEST(o_maximo_na_primeira_gaveta) {
    checa_int("o maximo na primeira gaveta", maiorNota(20, 2), 20,
              "na caixa {20, 8, 6, 9, 2} a maior nota e a da gaveta 0");
}

SM_TEST(o_maximo_na_ultima_gaveta) {
    checa_int("o maximo na ultima gaveta", maiorNota(1, 15), 15,
              "na caixa {1, 8, 6, 9, 15} a maior nota e a da gaveta 4");
}

SM_TEST(o_maximo_no_meio_da_caixa) {
    checa_int("o maximo no meio da caixa", maiorNota(2, 3), 9,
              "na caixa {2, 8, 6, 9, 3} a maior nota nao esta em nenhuma das pontas");
}

solutionCode:
int maiorNota(int primeira, int ultima) {
    int notas[5] = {primeira, 8, 6, 9, ultima};
    int maior = notas[0];
    for (int i = 1; i < 5; i++) {
        if (notas[i] >= maior) {
            maior = notas[i];
        }
    }
    return maior;
}
